const g=[[244,71,172],[255,123,95],[196,244,54],[72,142,232],[151,101,222],[87,215,161]],x=t=>t-Math.floor(t);function y(t,e,o){const r=Math.cos(o),n=Math.sin(o);return[t*r-e*n,t*n+e*r]}function z(t,e,o,r){const[n,i]=y(t-o.x,e-o.y,-o.rotation),s=n/o.size,c=i/o.size,M=Math.hypot(s,c),h=Math.atan2(c,s);if(o.type===0){const a=.72+Math.sin(h*3+o.seed+r*.7)*.12+Math.cos(h*5-o.seed)*.06;return M<a}if(o.type===1){const a=.68+Math.sin(c*3+o.seed)*.13,l=.56+Math.cos(s*2+r+o.seed)*.08;return Math.max(Math.abs(s)-a,Math.abs(c)-l)<0}const d=Math.abs(c-Math.sin(s*2.8+o.seed)*.22);return Math.abs(s)<.9&&d<.22+Math.cos(s*3)*.08}function w(t){const e=t.time(),o=t.rgb(27,18,57);t.clear(o);const r=11;for(let n=0;n<r;n+=1){const i=x(e*.085+n/r),s=.05+Math.pow(i,1.85)*.4,c=n*2.41+Math.sin(n*1.7)*.45,M=i*1.16,h={x:.5+Math.cos(c)*M,y:.5+Math.sin(c)*M,size:s,rotation:c+i*2.7+Math.sin(e*.5+n)*.2,seed:n*1.91,type:n%3,color:g[n%g.length]};for(let d=0;d<t.height;d+=1)for(let a=0;a<t.width;a+=1){const l=a/(t.width-1),f=d/(t.height-1);if(!z(l,f,h,e))continue;const u=.58+i*.42;t.pixel(a,d,t.rgb(h.color[0]*u,h.color[1]*u,h.color[2]*u))}}}export{w as draw};
